create or replace function public.append_shared_action_event(p_id uuid,p_episode_id uuid,p_property_id uuid,p_actor_id uuid,p_product text,p_action text,p_evidence text,p_phase text,p_request jsonb,p_before jsonb,p_after jsonb,p_result jsonb,p_links jsonb default '{}')
returns jsonb language plpgsql security invoker set search_path='' as $$
declare organization uuid;e public.shared_action_events;episode public.shared_action_episodes;origin text;job uuid;attempt uuid;context_id uuid;
begin
 if p_id is null or p_episode_id is null or p_actor_id is null or jsonb_typeof(p_request) is distinct from 'object' or jsonb_typeof(p_result) is distinct from 'object'
  or length(coalesce(p_request::text,''))+length(coalesce(p_before::text,''))+length(coalesce(p_after::text,''))+length(coalesce(p_result::text,''))>32768 then raise exception 'Invalid action event';end if;
 if p_product not in ('platform','siteforge','lumaleasing','propertyaudit','brandforge','tourspark','leadpulse','crm','forgestudio','reviewflow','marketvision','bi','knowledge','property','integrations','reports','pipelines','settings','team','agency')
  or p_action not in ('market.handoff.prepared','market.handoff.decided','market.brief.requested','market.brief.recovered','market.brief.reviewed','market.brief.exported','market.source.requested','market.source.stopped','market.source.recovered','market.listing.saved','market.listing.removed','market.extraction.requested','market.extraction.stopped','market.extraction.recovered','market.extraction.rebased','market.extraction.applied','market.competitor.saved','market.competitor.archived','market.competitor.restored','market.unit.saved','market.unit.removed','market.configuration.saved','review.testimonial.approved','review.testimonial.revoked','review.insights.saved','review.batch.prepared','review.batch.approved','review.batch.stopped','review.batch.recovered','review.configuration.saved','review.connection.saved','review.connection.disconnected','review.intake.requested','review.intake.applied','review.intake.stopped','review.intake.recovered','review.intake.rebased','review.publication.prepared','review.publication.reported','review.publication.cancelled','review.publication.uncertain','review.response.draft_saved','review.response.approved','review.response.rejected','review.response.generation_requested','review.response.generation_started','review.response.generation_result_received','review.response.generation_completed','review.response.generation_stopped','review.response.generation_recovered','review.case.created','review.case.updated','review.case.resolved','review.case.dismissed','review.case.reopened','review.case.note_added','review.ticket.created','review.ticket.updated','review.ticket.reopened','review.analysis.started','review.analysis.result_received','review.analysis.requested','review.analysis.completed','review.analysis.stopped','review.analysis.recovered','studio.credentials.renewal_requested','studio.credentials.renewal_completed','studio.app_configuration.save','studio.app_configuration.disable','studio.connection.disconnected','studio.authorization.started','studio.authorization.cancelled','studio.authorization.applied','studio.configuration.saved','studio.metrics.requested','studio.metrics.reported','studio.metrics.reviewed','studio.attribution.reviewed','studio.media.requested','studio.media.stopped','studio.media.recovered','studio.media.completed','studio.asset.saved','studio.asset.reviewed','studio.asset.archived','studio.asset.restored','studio.asset.upload.requested','studio.asset.uploaded','studio.asset.replaced','studio.asset.upload.recovered','studio.sources.refreshed','studio.generation.recovered','studio.generation.requested','studio.generation.stopped','studio.publication.recovery_reviewed','studio.publications.scheduled','studio.publication.cancel','studio.publication.reschedule','studio.brief.saved','studio.package.created','studio.revision.saved','studio.revision.reviewed','crm.qualification.prepared','crm.qualification.approved','crm.qualification.recovered','crm.qualification.activated','crm.qualification.stopped','crm.qualification.completed','crm.bulk.prepared','crm.bulk.approved','crm.bulk.stopped','crm.delivery.recovery_requested','crm.delivery.recovery_checked','crm.delivery.approved','crm.delivery.requested','crm.delivery.completed','crm.delivery.cancelled','crm.delivery.reconciled','crm.mapping.saved','crm.mapping.previewed','crm.mapping.approved','crm.operation.requested','crm.operation.completed','crm.operation.stopped','lead.score.reviewed','lead.engagement.recorded','lead.engagement.corrected','lead.score.recalculated','lead.scoring.started','lead.scoring.completed','lead.scoring.cancelled','console.page.viewed','workflow.pause','workflow.resume','workflow.stop','workflow.delivery.reviewed','tour.outcome.recorded','tour.no_show.corrected','tour.rescheduled','tour.cancelled','tour.reminder.reviewed','tour.booked','tour.timezone.set','tour.schedule_delivery.reviewed','tour.calendar_change.reviewed','tour.calendar_event.bound','brand.research.requested','brand.research.completed','brand.research.cancelled','brand.source.saved','brand.asset.upload.requested','brand.asset.uploaded','brand.asset.reviewed','brand.import.previewed','brand.operation.requested','brand.operation.cancelled','brand.brief.saved','brand.section.generated','brand.section.regenerated','brand.section.edited','brand.section.approved','brand.contract.generated','brand.contract.imported','brand.export.created','brand.revision.started','brand.visuals.generated','brand.knowledge.published','calendar.disconnected','integration.authorization.completed','integration.authorization.started','integration.authorization.cancelled','integration.authorization.failed','email.disconnected','integration.invite.created','integration.invite.revoked','integration.replacement.requested','integration.account.replaced','luma.configuration.created','luma.configuration.saved') then raise exception 'Unregistered action';end if;
 if p_action='console.page.viewed' then
  if p_evidence<>'browser_observed' or p_phase<>'observed' or p_request-array['path']<>'{}' or p_before is not null or p_after is not null or p_links<>'{}' then raise exception 'Invalid observation';end if;
 elsif p_action in ('calendar.disconnected','integration.authorization.completed','integration.authorization.started','integration.authorization.cancelled','integration.authorization.failed','email.disconnected','integration.invite.created','integration.invite.revoked','integration.replacement.requested','integration.account.replaced') then
  if p_product<>'integrations' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid connection evidence';end if;
 elsif p_action like 'review.%' then
  if p_product<>'reviewflow' or p_evidence<>'server_confirmed' or p_phase not in('succeeded','failed') then raise exception 'Invalid review evidence';end if;
 elsif p_action like 'market.%' then
  if p_product<>'marketvision' or p_evidence<>'server_confirmed' or p_phase<>'succeeded' then raise exception 'Invalid market evidence';end if;
 elsif p_action like 'studio.%' then
  if p_product<>'forgestudio' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid editorial evidence';end if;
 elsif p_action like 'crm.%' then
  if p_product<>'crm' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid CRM evidence';end if;
 elsif p_action like 'lead.%' then
  if p_product<>'leadpulse' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid scoring evidence';end if;
 elsif p_action like 'brand.%' then
  if p_product<>'brandforge' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid brand evidence';end if;
 elsif p_action in ('luma.configuration.created','luma.configuration.saved') then
  if p_product<>'lumaleasing' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid configuration evidence';end if;
 else
  if p_product<>'tourspark' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid workflow evidence';end if;
 end if;
 select p.org_id into organization from public.properties p join public.profiles u on p.org_id=u.org_id where p.id=p_property_id and u.id=p_actor_id;
 if organization is null then return '{"state":"forbidden"}';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_property_id::text,12));
 job:=nullif(p_links->>'jobId','')::uuid;attempt:=nullif(p_links->>'attemptId','')::uuid;context_id:=nullif(p_links->>'contextId','')::uuid;
 select * into e from public.shared_action_events where id=p_id;
 if found then
  if (e.episode_id,e.property_id,e.actor_id,e.product,e.action,e.evidence,e.phase,e.request,e.before_state,e.after_state,e.result,e.shared_job_ref,e.shared_attempt_ref,e.context_snapshot_ref)
   is distinct from (p_episode_id,p_property_id,p_actor_id,p_product,p_action,p_evidence,p_phase,p_request,p_before,p_after,p_result,job,attempt,context_id) then return '{"state":"request_conflict"}';end if;
  return jsonb_build_object('state','replayed','eventId',e.id);
 end if;
 if job is not null and not exists(select 1 from public.shared_jobs where id=job and org_id=organization and property_id=p_property_id) then return '{"state":"link_conflict"}';end if;
 if attempt is not null and not exists(select 1 from public.shared_action_attempts where id=attempt and org_id=organization and property_id=p_property_id and (job is null or job_id=job)) then return '{"state":"link_conflict"}';end if;
 if context_id is not null and not exists(select 1 from public.shared_context_snapshots where id=context_id and org_id=organization and property_id=p_property_id) then return '{"state":"link_conflict"}';end if;
 origin:=case when p_action like 'market.%' then 'console' when p_action in('review.response.generation_started','review.response.generation_result_received','review.response.generation_completed') or(p_action='review.response.draft_saved' and p_result->>'origin'='model_result') then 'workflow' when p_action in('review.analysis.started','review.analysis.result_received','review.analysis.completed') then 'workflow' when p_action like 'review.%' then 'console' when p_action in('studio.media.completed','studio.credentials.renewal_completed') then 'workflow' when p_action like 'studio.%' then 'console' when p_action like 'lead.%' or p_action like 'crm.%' then 'console' when p_action in ('console.page.viewed','luma.configuration.created','luma.configuration.saved') then 'console' else 'workflow' end;
 insert into public.shared_action_episodes(id,org_id,property_id,actor_id,origin)values(p_episode_id,organization,p_property_id,p_actor_id,origin) on conflict(id) do nothing;
 select * into episode from public.shared_action_episodes where id=p_episode_id;
 if (episode.org_id,episode.property_id,episode.actor_id,episode.origin) is distinct from (organization,p_property_id,p_actor_id,origin) then return '{"state":"episode_conflict"}';end if;
 insert into public.shared_action_events(id,episode_id,org_id,property_id,actor_id,product,action,evidence,phase,request,before_state,after_state,result,shared_job_ref,shared_attempt_ref,context_snapshot_ref)
 values(p_id,p_episode_id,organization,p_property_id,p_actor_id,p_product,p_action,p_evidence,p_phase,p_request,p_before,p_after,p_result,job,attempt,context_id);
 return jsonb_build_object('state','recorded','eventId',p_id);
end; $$;

-- Private, immutable draft intent; the report retains all original source records.
create table public.marketvision_handoffs(
 id uuid primary key references public.shared_jobs(id),org_id uuid not null references public.organizations(id),property_id uuid not null references public.properties(id)on delete cascade,actor_id uuid not null references public.profiles(id),
 brief_id uuid not null references public.marketvision_briefs(id),recommendation_id uuid not null,review_id uuid not null references public.marketvision_decisions(id),context_id uuid not null references public.shared_context_snapshots(id),attempt_id uuid not null unique references public.shared_action_attempts(id),target_id uuid not null unique,
 input jsonb not null,input_hash text not null,draft jsonb not null,draft_hash text not null,source_hash text not null,report_hash text not null,
 state text not null default 'prepared'check(state in('prepared','completed','rejected','withdrawn')),version integer not null default 1,
 decision_id uuid,decision_actor uuid references public.profiles(id),receipt jsonb,created_at timestamptz not null default clock_timestamp(),finished_at timestamptz
);
create index marketvision_handoff_history on public.marketvision_handoffs(property_id,created_at desc,id desc);
create index marketvision_handoff_org on public.marketvision_handoffs(org_id);
create index marketvision_handoff_actor on public.marketvision_handoffs(actor_id);
create index marketvision_handoff_context on public.marketvision_handoffs(context_id);
create index marketvision_handoff_review on public.marketvision_handoffs(review_id);
create index marketvision_handoff_decision_actor on public.marketvision_handoffs(decision_actor);
create unique index marketvision_handoff_active_review on public.marketvision_handoffs(brief_id,recommendation_id,review_id)where state in('prepared','completed');
alter table public.marketvision_handoffs enable row level security;
revoke all on public.marketvision_handoffs from public,anon,authenticated;
grant all on public.marketvision_handoffs to service_role;
create policy marketvision_handoff_service on public.marketvision_handoffs for all to service_role using(true)with check(true);
create function public.guard_marketvision_handoff()returns trigger language plpgsql security invoker set search_path=''as $$begin
 if tg_op='DELETE'then if not exists(select 1 from public.properties where id=old.property_id)then return old;end if;raise exception 'Retain the saved handoff history';end if;
 if(to_jsonb(new)-array['state','version','decision_id','decision_actor','receipt','finished_at'])is distinct from(to_jsonb(old)-array['state','version','decision_id','decision_actor','receipt','finished_at'])then raise exception 'Prepare a new handoff to change the saved draft';end if;
 if old.state<>'prepared'or new.state='prepared'or new.decision_id is null or new.decision_actor is null or new.receipt is null or new.finished_at is null then raise exception 'A handoff needs one final reviewed decision';end if;
 new.version:=old.version+1;return new;
end$$;
create trigger marketvision_handoff_guard before update or delete on public.marketvision_handoffs for each row execute function public.guard_marketvision_handoff();
create or replace function public.marketvision_decision_finish(p_id uuid,p_property_id uuid,p_actor_id uuid,p_kind text,p_resource_id uuid,p_input jsonb,p_before jsonb,p_after jsonb,p_result jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare event jsonb;begin
 insert into public.marketvision_decisions(id,org_id,property_id,actor_id,kind,resource_id,input,input_hash,before_state,after_state,result)values(p_id,(select org_id from public.properties where id=p_property_id),p_property_id,p_actor_id,p_kind,p_resource_id,p_input,public.crm_configuration_hash(p_input),p_before,p_after,p_result);
 event:=public.append_shared_action_event(p_id,p_id,p_property_id,p_actor_id,'marketvision','market.'||p_kind,'server_confirmed','succeeded',jsonb_build_object('inputHash',public.crm_configuration_hash(p_input),'resourceId',p_resource_id),case when p_before is not null then jsonb_build_object('version',p_before->'version','stateHash',public.crm_configuration_hash(p_before)) end,case when p_after is not null then jsonb_build_object('version',p_after->'version','stateHash',public.crm_configuration_hash(p_after)) end,p_result,case when (p_kind like 'extraction.%'or p_kind like 'source.%'or p_kind like 'brief.%'or p_kind like 'handoff.%') then coalesce((select jsonb_build_object('jobId',j.id,'contextId',j.context_snapshot_id,'attemptId',case when p_kind like 'handoff.%'then (select h.attempt_id from public.marketvision_handoffs h where h.id=j.id)else null end)from public.shared_jobs j where j.id=(p_result->>'requestId')::uuid and j.property_id=p_property_id),'{}')else '{}'end);
 if event->>'state' not in('recorded','replayed') then raise exception 'Market decision history could not be saved';end if;return p_result||'{"state":"saved"}';
end$$;
create function public.prepare_marketvision_handoff(p_id uuid,p_property_id uuid,p_actor_id uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare prior jsonb;r public.marketvision_briefs;rec jsonb;review public.marketvision_decisions;snapshot jsonb;draft jsonb;ctx uuid:=gen_random_uuid();attempt uuid:=gen_random_uuid();target uuid:=gen_random_uuid();existing uuid;begin
 prior:=public.marketvision_decision_start(p_id,p_property_id,p_actor_id,'handoff.prepared',p_input);if prior->>'state'<>'new'then return prior;end if;
 if(p_input-array['briefId','expectedVersion','recommendationId','expectedReviewId','title','objective','channel','format','reason'])<>'{}'
 or length(trim(coalesce(p_input->>'title','')))not between 1 and 300 or length(trim(coalesce(p_input->>'objective','')))not between 1 and 2000
 or coalesce(p_input->>'channel','')not in('facebook','instagram','linkedin','tiktok','x')or coalesce(p_input->>'format','')not in('text','image','video','reel','carousel','story')then raise exception 'Review the saved draft title, objective, channel and format';end if;
 if(p_input->>'channel'='instagram'and p_input->>'format'='text')or(p_input->>'channel'='tiktok'and p_input->>'format'not in('video','reel'))then return '{"state":"invalid_format"}';end if;
 select * into r from public.marketvision_briefs where id=(p_input->>'briefId')::uuid and property_id=p_property_id and org_id=(select org_id from public.properties where id=p_property_id)for update;if not found then return '{"state":"not_found"}';end if;
 if r.state<>'ready'or r.version is distinct from(p_input->>'expectedVersion')::integer then return '{"state":"stale_report"}';end if;
 select value into rec from jsonb_array_elements(r.result->'recommendations')where value->>'id'=p_input->>'recommendationId';if rec is null then return '{"state":"not_found"}';end if;
 -- Source repair prompts need source repair, not a marketing draft.
 if rec->>'kind'is distinct from 'comparison_review'then return '{"state":"source_review_required"}';end if;
 select * into review from public.marketvision_decisions where property_id=p_property_id and org_id=r.org_id and resource_id=r.id and kind='brief.reviewed'and input->>'recommendationId'=p_input->>'recommendationId'order by created_at desc,id desc limit 1;
 if review.id is null or review.id is distinct from(p_input->>'expectedReviewId')::uuid or review.input->>'decision'<>'consider'then return '{"state":"stale_review"}';end if;
 select id into existing from public.marketvision_handoffs where brief_id=r.id and recommendation_id=(rec->>'id')::uuid and review_id=review.id and state in('prepared','completed');if found then return jsonb_build_object('state','handoff_exists','handoffId',existing);end if;
 snapshot:=public.marketvision_brief_sources(p_property_id,p_actor_id,(r.input->>'windowDays')::integer);if snapshot->>'state'<>'ready'or public.marketvision_brief_source_hash(snapshot)is distinct from r.source_hash then return '{"state":"source_changed"}';end if;
 draft:=jsonb_build_object('title',trim(p_input->>'title'),'objective',trim(p_input->>'objective'),'topic','Market comparison for human review','audience',null,
 'sourceFacts',jsonb_build_array(jsonb_build_object('text',left(rec->>'rationale',1000),'source','marketvision_proposal:'||p_id||':report:'||r.id||':recommendation:'||(rec->>'id'))),
 'constraints',jsonb_build_object('mustAvoid',jsonb_build_array('Do not present competitor prices, availability or amenities as facts about this property.','Do not claim that this comparison proves a rent change, revenue lift or a business outcome.'),'mustInclude',jsonb_build_array('Use approved property and brand sources for any advertising claim. Market signals guide topic, timing or format only.')),
 'channels',jsonb_build_array(p_input->>'channel'),'connectionIds','[]'::jsonb,'assetIds','[]'::jsonb,'formatPlan',jsonb_build_array(jsonb_build_object('platform',p_input->>'channel','contentFormat',p_input->>'format','quantity',1)),'schedulingWindow','{}'::jsonb);
 insert into public.shared_context_snapshots(id,org_id,property_id,source_domain,source_ref,context_hash,context_payload,captured_by)values(ctx,r.org_id,p_property_id,'marketvision.handoff',p_id::text,public.crm_configuration_hash(jsonb_build_object('reportHash',r.result_hash,'recommendation',rec,'reviewId',review.id,'draft',draft)),jsonb_build_object('reportId',r.id,'reportHash',r.result_hash,'sourceHash',r.source_hash,'reportContextId',r.context_id,'recommendation',rec,'reviewId',review.id,'draft',draft),p_actor_id::text);
 insert into public.shared_jobs(id,org_id,property_id,domain,subject_type,subject_id,lifecycle_status,status_reason,dedupe_key,payload,context_snapshot_id,attempt_count,max_attempts,stage,progress,current_step)values(p_id,r.org_id,p_property_id,'marketvision.handoff','marketvision_brief',r.id::text,'queued','approval_required',p_id::text,jsonb_build_object('handoffId',p_id,'briefId',r.id),ctx,0,1,'awaiting_approval',0,'Review the exact ForgeStudio draft in MarketVision');
 insert into public.shared_action_attempts(id,job_id,org_id,property_id,action_type,lifecycle_status,proposal_decision_status,execution_status,requested_by,request_payload,execution_payload,policy_snapshot,policy_reason)values(attempt,p_id,r.org_id,p_property_id,'forgestudio_messaging_brief','queued','proposed','pending_approval',p_actor_id,jsonb_build_object('handoffId',p_id,'briefId',r.id,'recommendationId',rec->>'id','reviewId',review.id),draft,'{"policy":"marketvision.saved-handoff","version":"2026-09-22"}',p_input->>'reason');
 insert into public.marketvision_handoffs(id,org_id,property_id,actor_id,brief_id,recommendation_id,review_id,context_id,attempt_id,target_id,input,input_hash,draft,draft_hash,source_hash,report_hash)values(p_id,r.org_id,p_property_id,p_actor_id,r.id,(rec->>'id')::uuid,review.id,ctx,attempt,target,p_input,public.crm_configuration_hash(p_input),draft,public.crm_configuration_hash(draft),r.source_hash,r.result_hash);
 return public.marketvision_decision_finish(p_id,p_property_id,p_actor_id,'handoff.prepared',p_id,p_input,null,jsonb_build_object('version',1,'state','prepared'),jsonb_build_object('requestId',p_id,'handoffId',p_id,'version',1,'attemptId',attempt,'draftHash',public.crm_configuration_hash(draft),'draftCreated',false,'externalDelivery',false));
end$$;
create function public.decide_marketvision_handoff(p_id uuid,p_property_id uuid,p_actor_id uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare prior jsonb;h public.marketvision_handoffs;r public.marketvision_briefs;review uuid;snapshot jsonb;result jsonb;terminal text;decision text;manager boolean;begin
 prior:=public.marketvision_decision_start(p_id,p_property_id,p_actor_id,'handoff.decided',p_input);if prior->>'state'<>'new'then return prior;end if;
 if(p_input-array['handoffId','expectedVersion','draftHash','decision','reason'])<>'{}'or coalesce(p_input->>'decision','')not in('approve','reject','withdraw')then raise exception 'Review the exact saved handoff and decision';end if;
 select * into h from public.marketvision_handoffs where id=(p_input->>'handoffId')::uuid and property_id=p_property_id and org_id=(select org_id from public.properties where id=p_property_id)for update;if not found then return '{"state":"not_found"}';end if;
 select role in('admin','manager')into manager from public.profiles where id=p_actor_id and org_id=h.org_id;
 if not coalesce(manager,false)and not(p_input->>'decision'='withdraw'and h.actor_id=p_actor_id)then return '{"state":"manager_required"}';end if;
 if h.state<>'prepared'or h.version is distinct from(p_input->>'expectedVersion')::integer or h.draft_hash is distinct from p_input->>'draftHash'then return '{"state":"stale_handoff"}';end if;
 if p_input->>'decision'='approve'then
  if not exists(select 1 from public.profiles where id=h.actor_id and org_id=h.org_id)then return '{"state":"requester_unavailable"}';end if;
  select * into r from public.marketvision_briefs where id=h.brief_id and property_id=p_property_id and org_id=h.org_id;
  if r.result_hash is distinct from h.report_hash then return '{"state":"stale_report"}';end if;
  select id into review from public.marketvision_decisions where resource_id=h.brief_id and property_id=p_property_id and org_id=h.org_id and kind='brief.reviewed'and input->>'recommendationId'=h.recommendation_id::text order by created_at desc,id desc limit 1;
  if review is distinct from h.review_id then return '{"state":"stale_review"}';end if;
  snapshot:=public.marketvision_brief_sources(p_property_id,p_actor_id,(r.input->>'windowDays')::integer);if snapshot->>'state'<>'ready'or public.marketvision_brief_source_hash(snapshot)is distinct from h.source_hash then return '{"state":"source_changed"}';end if;
  result:=public.save_forgestudio_brief(h.target_id,p_property_id,p_actor_id,h.draft);
  if result->>'state'not in('saved','replayed')then raise exception 'The reviewed draft could not be created atomically';end if;
 end if;
 terminal:=case p_input->>'decision'when 'approve'then 'completed'when 'reject'then 'rejected'else 'withdrawn'end;decision:=case when terminal='completed'then 'approved'else 'denied'end;
 result:=jsonb_build_object('requestId',h.id,'handoffId',h.id,'version',h.version+1,'decision',p_input->>'decision','draftHash',h.draft_hash,'reportHash',h.report_hash,'contentBriefId',case when terminal='completed'then h.target_id end,'draftCreated',terminal='completed','externalDelivery',false,'generationStarted',false,'businessOutcome','unknown');
 update public.marketvision_handoffs set state=terminal,decision_id=p_id,decision_actor=p_actor_id,receipt=result,finished_at=clock_timestamp()where id=h.id;
 update public.shared_action_attempts set lifecycle_status=case when terminal='completed'then 'succeeded'else 'cancelled'end,proposal_decision_status=decision,execution_status=case when terminal='completed'then 'executed'else 'cancelled'end,reviewed_by=p_actor_id,decided_at=clock_timestamp(),executed_at=case when terminal='completed'then clock_timestamp()end,execution_result=result,policy_reason=p_input->>'reason',updated_at=clock_timestamp()where id=h.attempt_id;
 update public.shared_jobs set lifecycle_status=case when terminal='completed'then 'succeeded'else 'cancelled'end,status_reason='handoff_'||terminal,finished_at=clock_timestamp(),stage=terminal,progress=100,current_step=case when terminal='completed'then 'Reviewed draft created in ForgeStudio'else 'Handoff '||terminal end,attempt_count=case when terminal='completed'then 1 else 0 end,updated_at=clock_timestamp()where id=h.id;
 insert into public.shared_approvals(id,action_attempt_id,org_id,property_id,decision_status,decision_reason,reviewer_profile_id,decision_payload)values(p_id,h.attempt_id,h.org_id,p_property_id,decision,p_input->>'reason',p_actor_id,result);
 insert into public.shared_policy_decisions(id,org_id,property_id,job_id,action_attempt_id,policy_name,policy_version,decision_status,decision_reason,decision_payload)values(p_id,h.org_id,p_property_id,h.id,h.attempt_id,'marketvision.saved-handoff','2026-09-22',decision,p_input->>'reason',result);
 return public.marketvision_decision_finish(p_id,p_property_id,p_actor_id,'handoff.decided',h.id,p_input,jsonb_build_object('version',h.version,'state',h.state),jsonb_build_object('version',h.version+1,'state',terminal),result);
end$$;
create function public.read_marketvision_handoffs(p_property_id uuid,p_actor_id uuid,p_brief_id uuid default null,p_handoff_id uuid default null,p_cursor uuid default null)returns jsonb language plpgsql stable security invoker set search_path=''as $$
declare h public.marketvision_handoffs;anchor public.marketvision_handoffs;items jsonb;organization uuid;snapshot jsonb;r public.marketvision_briefs;review uuid;begin
 select p.org_id into organization from public.properties p join public.profiles a on a.org_id=p.org_id where p.id=p_property_id and a.id=p_actor_id;if not found then return '{"state":"forbidden"}';end if;
 if p_handoff_id is not null then
  select * into h from public.marketvision_handoffs where id=p_handoff_id and property_id=p_property_id and org_id=organization and(p_brief_id is null or brief_id=p_brief_id);if not found then return '{"state":"not_found"}';end if;
  select * into r from public.marketvision_briefs where id=h.brief_id and property_id=p_property_id;
  snapshot:=public.marketvision_brief_sources(p_property_id,p_actor_id,(r.input->>'windowDays')::integer);
  select id into review from public.marketvision_decisions where resource_id=h.brief_id and property_id=p_property_id and kind='brief.reviewed'and input->>'recommendationId'=h.recommendation_id::text order by created_at desc,id desc limit 1;
  return jsonb_build_object('state','ready','handoff',to_jsonb(h),'sourceChanged',case when snapshot->>'state'='ready'then public.marketvision_brief_source_hash(snapshot)is distinct from h.source_hash else null end,'reviewChanged',review is distinct from h.review_id,'canApprove',exists(select 1 from public.profiles where id=p_actor_id and org_id=h.org_id and role in('admin','manager')),'canWithdraw',p_actor_id=h.actor_id or exists(select 1 from public.profiles where id=p_actor_id and org_id=h.org_id and role in('admin','manager')));
 end if;
 if p_cursor is not null then select * into anchor from public.marketvision_handoffs where id=p_cursor and property_id=p_property_id and org_id=organization and(p_brief_id is null or brief_id=p_brief_id);if not found then return '{"state":"cursor_changed"}';end if;end if;
 select coalesce(jsonb_agg(q.item order by q.created_at desc,q.id desc),'[]')into items from(select entry.created_at,entry.id,jsonb_build_object('id',entry.id,'briefId',entry.brief_id,'recommendationId',entry.recommendation_id,'state',entry.state,'createdAt',entry.created_at,'title',entry.draft->>'title','reason',entry.input->>'reason')item from public.marketvision_handoffs entry where entry.property_id=p_property_id and entry.org_id=organization and(p_brief_id is null or entry.brief_id=p_brief_id)and(p_cursor is null or(entry.created_at,entry.id)<(anchor.created_at,anchor.id))order by entry.created_at desc,entry.id desc limit 21)q;
 return jsonb_build_object('state','ready','handoffs',case when jsonb_array_length(items)>20 then items-20 else items end,'nextCursor',case when jsonb_array_length(items)>20 then items->19->>'id'else null end);
end$$;
-- Generic approval/replay must never bypass the saved handoff transaction.
create function public.guard_marketvision_handoff_projection()returns trigger language plpgsql security invoker set search_path=''as $$
declare h public.marketvision_handoffs;job_id uuid;expected text;begin
 if tg_table_name='shared_jobs'then job_id:=new.id;else if tg_table_name='shared_action_attempts'then job_id:=new.job_id;else select a.job_id into job_id from public.shared_action_attempts a where a.id=new.action_attempt_id;end if;end if;
 select * into h from public.marketvision_handoffs where id=job_id;if not found or not exists(select 1 from public.properties where id=h.property_id)then return new;end if;
 if tg_table_name='shared_jobs'then
  expected:=case h.state when 'prepared'then 'queued'when 'completed'then 'succeeded'else 'cancelled'end;
  if new.lifecycle_status<>expected or new.domain<>'marketvision.handoff'or new.context_snapshot_id is distinct from h.context_id or(new.org_id,new.property_id)is distinct from(h.org_id,h.property_id)then raise exception 'Review this handoff in MarketVision';end if;
 elsif tg_table_name='shared_action_attempts'then
  expected:=case h.state when 'prepared'then 'proposed'when 'completed'then 'approved'else 'denied'end;
  if new.id<>h.attempt_id or new.proposal_decision_status<>expected or new.execution_payload is distinct from h.draft or new.action_type<>'forgestudio_messaging_brief'or new.reviewed_by is distinct from h.decision_actor or new.execution_result is distinct from h.receipt or new.execution_status<>(case h.state when 'prepared'then 'pending_approval'when 'completed'then 'executed'else 'cancelled'end) or new.lifecycle_status<>(case h.state when 'prepared'then 'queued'when 'completed'then 'succeeded'else 'cancelled'end) or(new.org_id,new.property_id)is distinct from(h.org_id,h.property_id)then raise exception 'Review this handoff in MarketVision';end if;
 else
  if h.state='prepared'or new.id is distinct from h.decision_id or new.decision_status<>(case when h.state='completed'then 'approved'else 'denied'end) or new.reviewer_profile_id is distinct from h.decision_actor or new.decision_payload is distinct from h.receipt then raise exception 'Review this handoff in MarketVision';end if;
 end if;return new;
end$$;
create trigger marketvision_handoff_job_projection before update on public.shared_jobs for each row execute function public.guard_marketvision_handoff_projection();
create trigger marketvision_handoff_attempt_projection before insert or update on public.shared_action_attempts for each row execute function public.guard_marketvision_handoff_projection();
create trigger marketvision_handoff_approval_projection before insert or update on public.shared_approvals for each row execute function public.guard_marketvision_handoff_projection();
revoke all on function public.prepare_marketvision_handoff(uuid,uuid,uuid,jsonb),public.decide_marketvision_handoff(uuid,uuid,uuid,jsonb),public.read_marketvision_handoffs(uuid,uuid,uuid,uuid,uuid),public.guard_marketvision_handoff(),public.guard_marketvision_handoff_projection()from public,anon,authenticated;
grant execute on function public.prepare_marketvision_handoff(uuid,uuid,uuid,jsonb),public.decide_marketvision_handoff(uuid,uuid,uuid,jsonb),public.read_marketvision_handoffs(uuid,uuid,uuid,uuid,uuid),public.guard_marketvision_handoff(),public.guard_marketvision_handoff_projection()to service_role;
